#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
    struct Node* child;
};

// function that flattens 
// a multilevel linked list
void flattenList(struct Node *head) {

    // Base case
    if (head == NULL)
        return;

    // Find tail node of first level
    struct Node *tail = head;
    while (tail->next != NULL)
        tail = tail->next;

    // One by one traverse through all nodes of first level 
    // linked list till we reach the tail node
    struct Node *curr = head;

    while (curr != NULL) {

        // If current node has a child
        if (curr->child) {

            // then append the child at the end of current list
            tail->next = curr->child;

            // and update the tail to new last node
            struct Node *tmp = curr->child;
            while (tmp->next)
                tmp = tmp->next;
            tail = tmp;

            // Remove link between curr and child node
            curr->child = NULL;
        }

        // Change current node
        curr = curr->next;
    }
}

void printList(struct Node* head) {
    struct Node* curr = head;
    while (curr != NULL) {
        printf("%d ", curr->data);
        curr = curr->next;
    }
    printf("\n");
}

struct Node* createNode(int new_data) {
    struct Node* new_node = 
    	(struct Node*)malloc(sizeof(struct Node));
    new_node->data = new_data;
    new_node->next = new_node->child = NULL;
    return new_node;
}

